-- Testing Manual CMS: module (one client process) -> section -> content block (header + markdown body).
-- Blocks belong to a module directly (section_id null) or to a section of that module.
-- Admin reads and writes everything; other signed-in users read only published modules and their sections/blocks.
-- Slugs are generated by the app on create and never change. `guide` is reserved (legacy pages at /manual/guide).

create table if not exists public.manual_modules (
  id uuid primary key default gen_random_uuid(),
  title text not null check (btrim(title) <> ''),
  slug text not null unique check (slug <> 'guide'),
  is_published boolean not null default false,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.manual_sections (
  id uuid primary key default gen_random_uuid(),
  module_id uuid not null references public.manual_modules(id) on delete cascade,
  title text not null check (btrim(title) <> ''),
  slug text not null,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (module_id, slug),
  unique (id, module_id)
);

create table if not exists public.manual_blocks (
  id uuid primary key default gen_random_uuid(),
  module_id uuid not null references public.manual_modules(id) on delete cascade,
  section_id uuid,
  header text not null check (btrim(header) <> ''),
  body text not null default '',
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- A block's section must belong to the same module.
  foreign key (section_id, module_id) references public.manual_sections (id, module_id) on delete cascade
);

create index if not exists manual_modules_sort_idx on public.manual_modules (sort_order);
create index if not exists manual_sections_module_sort_idx on public.manual_sections (module_id, sort_order);
create index if not exists manual_blocks_module_sort_idx on public.manual_blocks (module_id, section_id, sort_order);

alter table public.manual_modules enable row level security;
alter table public.manual_sections enable row level security;
alter table public.manual_blocks enable row level security;

drop policy if exists "manual modules: read" on public.manual_modules;
create policy "manual modules: read" on public.manual_modules
  for select to authenticated
  using ((select public.is_admin()) or is_published);

drop policy if exists "manual modules: admin write" on public.manual_modules;
create policy "manual modules: admin write" on public.manual_modules
  for all to authenticated
  using ((select public.is_admin()))
  with check ((select public.is_admin()));

drop policy if exists "manual sections: read" on public.manual_sections;
create policy "manual sections: read" on public.manual_sections
  for select to authenticated
  using (
    (select public.is_admin())
    or exists (select 1 from public.manual_modules m where m.id = manual_sections.module_id and m.is_published)
  );

drop policy if exists "manual sections: admin write" on public.manual_sections;
create policy "manual sections: admin write" on public.manual_sections
  for all to authenticated
  using ((select public.is_admin()))
  with check ((select public.is_admin()));

drop policy if exists "manual blocks: read" on public.manual_blocks;
create policy "manual blocks: read" on public.manual_blocks
  for select to authenticated
  using (
    (select public.is_admin())
    or exists (select 1 from public.manual_modules m where m.id = manual_blocks.module_id and m.is_published)
  );

drop policy if exists "manual blocks: admin write" on public.manual_blocks;
create policy "manual blocks: admin write" on public.manual_blocks
  for all to authenticated
  using ((select public.is_admin()))
  with check ((select public.is_admin()));
